from itertools import permutations

def is_leap_year(year):
    return year % 4 == 0

def days_in_month(month, year):
    days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if month == 2 and is_leap_year(year):
        return 29
    return days[month - 1]

def is_valid_date(day, month, year):
    if month < 1 or month > 12:
        return False
    if day < 1 or day > days_in_month(month, year):
        return False
    return True

def date_to_days(day, month, year):
    # Convert date to days since year 0
    total_days = 0
    # Add days for years
    for y in range(2000, 2000 + year):
        if is_leap_year(y):
            total_days += 366
        else:
            total_days += 365

    # Add days for months
    for m in range(1, month):
        total_days += days_in_month(m, 2000 + year)

    # Add days
    total_days += day
    return total_days

